reference_solution:
def carPooling(trips, capacity):
    if not trips:
        return True
    end = max(t[2] for t in trips)
    diff = [0] * (end + 2)
    for num, frm, to in trips:
        diff[frm] += num
        diff[to] -= num
    cur = 0
    for i in range(end + 1):
        cur += diff[i]
        if cur > capacity:
            return False
    return True

brute_force_solution:
def carPooling(trips, capacity):
    if not trips:
        return True
    end = max(t[2] for t in trips)
    for loc in range(end + 1):
        load = sum(num for num, f, t in trips if f <= loc < t)
        if load > capacity:
            return False
    return True

